      content: row.content,
      contentHash: row.content_hash,
      schemaVersion: row.schema_version,
      domain: row.domain,
      paradigm: "hypothesis",
      confidence: row.confidence,
      sourceType: row.source_type,
      sourceUri: row.source_uri,
      createdAt: row.created_at,
