  registry2.add({
    name: "reasoning_build",
    description: "\u6784\u5EFA\u63A8\u7406\u56FE (\u6DFB\u52A0\u524D\u63D0\u2192\u63A8\u7406\u2192\u7ED3\u8BBA\uFF0C\u81EA\u52A8\u68C0\u6D4B\u7A7A\u6D1E)",
    inputSchema: {
      premises: exports_external.array(exports_external.string()).describe("\u524D\u63D0\u5217\u8868"),
      conclusion: exports_external.string().optional().describe("\u7ED3\u8BBA")
    },
    handler: async (args) => {
      const dre = (await getKernelAsync()).getEngine();
      dre.reasoning.clear();
      const premiseNodes = args.premises.map((p) => dre.reasoning.addPremise(p));
      let conclusionNode = null;
      if (args.conclusion) {
        conclusionNode = dre.reasoning.addConclusion(args.conclusion, premiseNodes.map((n) => n.id));
      }
      const gaps = dre.reasoning.detectGaps();
      const stats = dre.reasoning.getStats();
      return {
        nodes: stats.totalNodes,
        edges: stats.totalEdges,
        gaps: gaps.length,
        gapDetails: gaps.map((g) => ({
          type: g.gapType,
          description: g.description,
          priority: g.priority,
          suggestedPrompt: g.suggestedPrompt
        }))
      };
    }
  });
