// ../../src/mcp/tool-registry.ts
async function defaultToolGuard(toolName, args) {
  const { monitorToolPayload: monitorToolPayload2 } = await Promise.resolve().then(() => (init_risk_monitor(), exports_risk_monitor));
  const verdict = await monitorToolPayload2(toolName, args);
  if (verdict === "require-approval") {
    const { getApprovalBridge: getApprovalBridge2 } = await Promise.resolve().then(() => (init_approval_bridge(), exports_approval_bridge));
    const approved = await getApprovalBridge2().request(toolName, args, {
      risk: "destructive",
      timeoutMs: 15000
    });
    if (!approved) {
      throw new Error(`[RiskMonitor] \u53CC\u5C42\u590D\u6838\u5224\u5B9A\u4E3A\u9AD8\u5371\u64CD\u4F5C\u4E14\u672A\u83B7\u6279\u51C6\uFF0C\u5DF2\u963B\u6B62\u6267\u884C: ${toolName}`);
    }
  }
}

class ToolRegistry {
  tools = [];
  guard;
  constructor(opts) {
    this.guard = opts?.guard ?? defaultToolGuard;
  }
  add(tool) {
    const guard = this.guard;
    const exposures = tool.exposure?.length ? [...tool.exposure] : ["internal"];
    const wrapped = {
      ...tool,
      exposure: exposures,
      handler: async (args) => {
        await guard(tool.name, args);
        return tool.handler(args);
      }
    };
    this.tools.push(wrapped);
    return this;
  }
  registerWithMcp(mcp, tools) {
    const selected = tools ?? this.tools;
    for (const tool of selected) {
      mcp.registerTool(tool.name, {
        description: tool.description,
        inputSchema: tool.inputSchema
      }, async (args) => {
        try {
          const result = await tool.handler(args);
          const text = tool.format === "text" ? String(result) : JSON.stringify(result, null, 2);
          return {
            content: [{ type: "text", text }]
          };
        } catch (e) {
          const errMsg = e instanceof Error ? e.message : String(e);
          const errStack = e instanceof Error ? e.stack ?? "" : "";
          return {
            content: [{
              type: "text",
              text: JSON.stringify({
                error: true,
                message: `\u5DE5\u5177 "${tool.name}" \u6267\u884C\u5931\u8D25: ${errMsg}`,
                stack: errStack || undefined
              }, null, 2)
            }],
            isError: true
          };
        }
      });
    }
  }
  buildHttpHandlers(tools) {
    const handlers = {};
    const selected = tools ?? this.tools;
    for (const tool of selected) {
      const originalHandler = tool.handler;
      handlers[tool.name] = async (args) => {
        try {
          return await originalHandler(args);
        } catch (e) {
          const errMsg = e instanceof Error ? e.message : String(e);
          return {
            error: true,
            message: `\u5DE5\u5177 "${tool.name}" \u6267\u884C\u5931\u8D25: ${errMsg}`
          };
        }
      };
    }
    return handlers;
  }
  getToolsMeta() {
    return this.tools.map((t) => ({ name: t.name, description: t.description }));
  }
  getToolNames() {
    return this.tools.map((t) => t.name);
  }
  get size() {
    return this.tools.length;
  }
  remove(name) {
    const before = this.tools.length;
    this.tools = this.tools.filter((t) => t.name !== name);
    return this.tools.length < before;
  }
  filterByExposure(allow) {
    const allowSet = new Set(allow);
    return this.tools.filter((t) => t.exposure?.some((e) => allowSet.has(e))).sort((a, b) => a.name.localeCompare(b.name));
  }
  getToolsByTags(tags) {
    const tagSet = new Set(tags);
    return this.tools.filter((t) => t.tags?.some((tag) => tagSet.has(tag)));
  }
  getToolsMetaFiltered(tags) {
    if (!tags || tags.length === 0)
      return this.getToolsMeta();
    const filtered = this.getToolsByTags(tags);
    return filtered.map((t) => ({ name: t.name, description: t.description }));
  }
}

// ../../src/dre/backend/mcp-server.ts
var mcp = new McpServer({ name: "Axiom DRE MCP Server", version: "0.1.0" });
var registry2 = new ToolRegistry;
registerDreTools(registry2);
registerMindTools(registry2);
registry2.registerWithMcp(mcp);
if (!process.env.DRE_DB_PATH) {
  process.env.DRE_DB_PATH = "./data/dre.db";
}
var useStdio = process.argv.includes("--stdio");
if (useStdio) {
  const stdio = new StdioServerTransport;
  await mcp.connect(stdio);
} else {
  const port = Number(process.env.DRE_MCP_PORT ?? "3001");
  const hostname2 = process.env.DRE_MCP_HOST ?? "127.0.0.1";
  const { WebStandardStreamableHTTPServerTransport: WebStandardStreamableHTTPServerTransport2 } = await Promise.resolve().then(() => (init_webStandardStreamableHttp(), exports_webStandardStreamableHttp));
  Bun.serve({
    port,
    hostname: hostname2,
    async fetch(req, server) {
      const reqServer = new McpServer({ name: "Axiom DRE MCP Server", version: "0.1.0" });
      registry2.registerWithMcp(reqServer);
      const httpTransport = new WebStandardStreamableHTTPServerTransport2({ sessionIdGenerator: undefined });
      await reqServer.connect(httpTransport);
      return httpTransport.handleRequest(req, server);
    }
  });
}
